// Generated by scripts/constants.mjs from the host's records (Settings/*.cs, the records they hold, SessionProfiles.cs);
// don't edit it by hand. The shapes of what the host sends, for the type checker: settings.json's, as the page has it in
// state.settings, and the shell profiles in state.profiles.

/** User preferences, in groups (SettingGroups.cs), persisted as plain JSON under %LOCALAPPDATA%\Termilly (SettingsFile); workspaces and history are encrypted separately. Custom profiles' variables are stored here too, so Settings warns against putting secrets in them. The page edits one group at a time (settings:save with the group's name). */
interface AppSettings {
  version: number;
  /** How terminals look and behave. */
  terminal: TerminalSettings;
  /** The app around the terminals. */
  interface: InterfaceSettings;
  /** The shells on offer. */
  shells: ShellSettings;
  /** Snippets and triggers. */
  commands: CommandSettings;
  /** When a terminal's agent tells the user. */
  notifications: NotificationSettings;
  /** What's kept between runs. */
  session: SessionSettings;
  /** Production safety and the paste warning. */
  safety: SafetySettings;
  /** Terminal logs. */
  logging: LoggingSettings;
  /** Recordings. */
  recording: RecordingSettings;
  /** SSH connections and forwards. */
  ssh: SshSettings;
  /** Coding agents. */
  agents: AgentSettings;
  /** The change preview. */
  changes: ChangeSettings;
  /** Termilly on servers. */
  remote: RemoteSettings;
  /** What the page remembers. */
  uiState: UiState;
  /** Data the page keeps here. */
  data: SettingsData;
}

/** How terminals look and behave: font, cursor, scrollback, images, the clipboard, colours, ports. */
interface TerminalSettings {
  fontFamily: string;
  fontSize: number;
  cursorStyle: string;
  cursorBlink: boolean;
  lineHeight: number;
  scrollback: number;
  textSmoothing: string;
  /** Images programs print (sixel, iTerm2's), shown inline. */
  inlineImages: boolean;
  /** Programs may set the clipboard (OSC 52). */
  programClipboard: boolean;
  /** Selecting text in a terminal copies it. */
  copyOnSelect: boolean;
  /** The terminal colour scheme's id (js/themes.js); null: the theme's own. */
  colors: string | null;
  /** A terminal's row shows the ports its programs listen on. */
  ports: boolean;
}

/** The app around the terminals: theme, its own font, the sidebar's activity and git status, updates, plugins. */
interface InterfaceSettings {
  theme: string;
  /** The app's font; null: the system's. */
  font: string | null;
  showActivity: boolean;
  confirmCloseWorkspace: boolean;
  gitStatus: boolean;
  checkForUpdates: boolean;
  disabledPlugins: string[] | null;
}

/** The shells on offer: the default, the user's own profiles and notes, shell integration, COM ports and consoles. */
interface ShellSettings {
  /** The profile new terminals start with; null: the first one. */
  defaultProfile: string | null;
  profiles: CustomProfile[] | null;
  /** A note per profile id, pinned to its terminals' headers. */
  notes: Record<string, string> | null;
  /** Shell integration: detected shells mark their prompts and commands. */
  integration: boolean;
  /** Docker containers and Kubernetes pods offered as profiles. */
  dynamicSources: boolean;
  serialPorts: SerialSettings[] | null;
  networkConsoles: NetworkConsole[] | null;
}

/** The user's saved commands (snippets) and the patterns watched in the output (triggers). */
interface CommandSettings {
  snippets: SnippetSetting[] | null;
  triggers: TriggerSetting[] | null;
}

/** When a terminal's agent tells the user, and the system-wide "next terminal that needs me" shortcut. */
interface NotificationSettings {
  needsInput: boolean;
  error: boolean;
  done: boolean;
  jumpHotkey: boolean;
}

/** What's kept between runs: the restore at start, history, hidden terminals' scrollback, background shells. */
interface SessionSettings {
  restore: string;
  historyDays: number;
  hiddenScrollback: number;
  /** Closed terminals' output is kept in the history. */
  saveOutput: boolean;
  /** Secrets are redacted from what's kept. */
  redactSecrets: boolean;
  /** Shells keep running in the background host after the window closes. */
  backgroundShells: boolean;
  backgroundAtSignIn: boolean;
}

/** Production safety: the environments terminals can be on, pasting into them, and the paste warning. */
interface SafetySettings {
  environments: EnvironmentSetting[] | null;
  prodPaste: string;
  prodTint: boolean;
  pasteWarning: boolean;
  /** The terminals (profile ids) the paste warning is off for. */
  pasteWarningOff: string[] | null;
}

/** Terminal logs: where, in which format, with timestamps, redacted, for how long, for which terminals. */
interface LoggingSettings {
  /** Null: Documents\Termilly\logs. */
  folder: string | null;
  format: string;
  timestamps: boolean;
  redact: boolean;
  /** 0: logs are kept. */
  keepDays: number;
  /** Terminals with these tags, or of these profiles, are logged from the start. */
  tags: string[] | null;
  profiles: string[] | null;
}

/** Recordings (asciicast): where, redacted, agents' terminals recorded too, and the size they stop at. */
interface RecordingSettings {
  /** Null: Documents\Termilly\recordings. */
  folder: string | null;
  redact: boolean;
  agents: boolean;
  maxMb: number;
}

/** SSH: keepalives, reconnecting, tmux on each host, the connections and port forwards defined in Settings. */
interface SshSettings {
  keepAlive: boolean;
  reconnect: boolean;
  /** A host's tmux session to attach to, by profile id. */
  attach: Record<string, string> | null;
  connections: SshConnection[] | null;
  forwards: PortForward[] | null;
}

/** Coding agents: the hooks, how many run before idle ones hibernate, reading terminals, the API, cost and usage. */
interface AgentSettings {
  /** Agent integration: Claude Code's hooks in Termilly's terminals. */
  integration: boolean;
  limit: number;
  /** A terminal lets agents read it unless it's SSH, production or sensitive. */
  readDefault: boolean;
  /** Scripts and agents may type into terminals (Settings › Terminal › API). */
  apiAllowInput: boolean;
  /** The sidebar's agent activity line. */
  line: string;
  costDisplay: string;
  claudeUsage: boolean;
  claudeLimits: boolean;
}

/** The change preview (Changes/, js/preview.js): where it opens, what it compares, and how it shows a change. */
interface ChangeSettings {
  enabled: boolean;
  placement: string;
  /** File paths in a terminal open the preview (Ctrl+click). */
  links: boolean;
  button: boolean;
  shortcut: boolean;
  source: string;
  view: string;
  compare: string;
  keep: string;
  context: number;
  highlight: boolean;
  wrap: boolean;
  maxFileKb: number;
  layout: string;
  follow: string;
  newFile: string;
  /** Files a shell command made or changed are listed too. */
  shellFiles: boolean;
}

/** Termilly's integration on servers: whether each host has it set up (RemoteIntegration). */
interface RemoteSettings {
  /** The setup's state, by host profile id. */
  setup: Record<string, string> | null;
}

/** What the page remembers rather than what the user sets: the tour, the Remote section, the window's colours. */
interface UiState {
  tourSeen: boolean;
  /** The sidebar's Remote section (js/remote.js): pinned hosts (profile ids). */
  remotePinned: string[] | null;
  /** When each host was last opened (ms). */
  remoteRecent: Record<string, number> | null;
  /** The theme's window colours, saved by the page (js/themes.js) for the window and loader at start-up. */
  windowColors: ThemeWindowColors | null;
  stopAgentConfirmed: boolean;
  /** An update the user chose to skip. */
  skippedVersion: string | null;
}

/** Data the page keeps in the settings file: the agent cost ledger, and the values last used in snippets. */
interface SettingsData {
  costLedger: Record<string, CostDay> | null;
  /** Each snippet's variables, as last filled in. */
  snippetValues: Record<string, Record<string, string>> | null;
}

/** A theme's colours for the window and start-up loader (#RRGGBB), and whether it's a light theme. */
interface ThemeWindowColors {
  background: string;
  frame: string;
  text: string;
  accent: string;
  light: boolean;
}

/** One day in the agent cost ledger (js/cost.js): the total, and per workspace name. */
interface CostDay {
  total: number;
  ws: Record<string, number> | null;
}

/** A saved command with {{placeholders}} (js/snippets.js); Enter pressed after it unless told not to. */
interface SnippetSetting {
  id: string;
  name: string;
  command: string;
  description: string | null;
  enter: boolean;
}

/** An environment terminals can be on (js/environments.js): production, staging. A terminal is on it when tagged with its id, or its SSH host matches one of the glob patterns (*-prod*, 10.20.*). */
interface EnvironmentSetting {
  id: string;
  label: string;
  color: string;
  patterns: string[] | null;
}

/** A regular expression run over each new output line (js/triggers.js). Action: highlight, capture (highlight and keep in the captured-lines panel), notify or attention. Scope: all, tag:&lt;name&gt; or profile:&lt;id&gt;. */
interface TriggerSetting {
  id: string;
  pattern: string;
  action: string;
  scope: string;
  enabled: boolean;
  name: string | null;
  color: string | null;
  caseSensitive: boolean;
}

/** A shell the user defined in Settings: any command line, with its own folder, variables and tags. */
interface CustomProfile {
  id: string;
  name: string;
  commandLine: string;
  workingDirectory: string | null;
  environment: Record<string, string> | null;
  tags: string[] | null;
  icon: string;
}

/** How a COM port is set up (Settings › Serial); one per port that's been changed from the defaults. */
interface SerialSettings {
  port: string;
  baud: number;
  dataBits: number;
  parity: string;
  stopBits: string;
  flow: string;
  lineEnding: string;
  log: boolean;
}

/** A console server or device reached over the network: raw TCP, or Telnet with RFC 2217 COM port control. */
interface NetworkConsole {
  id: string;
  name: string;
  host: string;
  port: number;
  protocol: string;
  baud: number | null;
  lineEnding: string;
  log: boolean;
  tags: string[] | null;
}

/** An SSH connection defined in Termilly: host, user, port and jump hosts, and how to sign in, as a reference only. Termilly never stores a secret: "agent" uses ssh-agent (or ssh's defaults), "key" and "sk" a key file (sk: a FIDO2 security key), "wincred" a password kept in Windows Credential Manager under , and "op" a 1Password reference (op://vault/item/field) read with the 1Password CLI. */
interface SshConnection {
  id: string;
  name: string;
  host: string;
  user: string | null;
  port: number | null;
  jump: string | null;
  identity: string;
  keyPath: string | null;
  secretRef: string | null;
  tags: string[] | null;
}

/** A port forward through an SSH connection or ~/.ssh/config host (Target: its profile id). Kind L forwards a local port to Dest, R a remote port back to Dest, D runs a SOCKS proxy on the local port. */
interface PortForward {
  id: string;
  name: string;
  target: string;
  kind: string;
  listenPort: number;
  destHost: string | null;
  destPort: number | null;
  autoStart: boolean;
}

/** Something a terminal can be opened with. Every kind of session (local shell, WSL, SSH, a custom command) is a local process under the pseudo console, so a profile is a command line plus where and how to start it. */
interface SessionProfile {
  id: string;
  name: string;
  description: string;
  icon: string;
  commandLine: string;
  source: string;
  workingDirectory: string | null;
  environment: Record<string, string> | null;
  tags: string[] | null;
}
